    const blocks = [
      { type: 'header', text: { type: 'plain_text', text: head.slice(0, 150), emoji: true } },
      { type: 'context', elements: [{ type: 'mrkdwn', text: `Score *${L.score}*. ${x.lib.SEGMENT_LABEL[L.segment] || L.segment}. Came from ${slackEsc(L.source)}. <${x.crmUrl}|${L.id}>` }] },
